import { describe, it, expect } from 'vitest';

describe('total', () => {
  it('빈 장바구니는 0', () => {
    expect(total([])).toBe(0);
  });
});

// 위 데모의 it/expect 와 하는 일이 같다 —
// 다르게 만드는 것은 러너·리포터·격리·병렬 실행 같은 주변 장치다

// 단위 — 순수 로직
expect(formatPrice(1234)).toBe('1,234원');

// 통합 — 컴포넌트 + 상태 + 요청(모의)
render(<Cart />);
await user.click(screen.getByRole('button', { name: '담기' }));
expect(screen.getByText('1개')).toBeVisible();

// E2E — 진짜 브라우저, 진짜(또는 그에 가까운) 서버
await page.goto('/');
await page.getByRole('button', { name: '결제' }).click();
await expect(page.getByText('주문 완료')).toBeVisible();

// 나쁨 — 왜 깨졌는지 모른다
expect(result).toBe(true);

// 좋음 — 값이 보이게
expect(result.status).toBe('success');
expect(rows.map(r => r.id)).toEqual([1, 2, 3]);

// 조건이 복잡하면 메시지를 붙인다
expect(total, '쿠폰 적용 후 합계').toBe(500);

// MSW — 코드는 진짜 fetch 를 쓰고, 테스트가 응답만 정한다
const server = setupServer(
  http.get('/api/cart', () => HttpResponse.json({ items: [] })),
);
beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

// 이렇게 하면 같은 가짜를 개발 서버·E2E 에서도 재사용할 수 있다

// 사용자 이벤트를 흉내 낸다 (진짜 키보드·마우스 순서대로)
const user = userEvent.setup();
await user.type(screen.getByLabelText('메일'), 'a@b.com');
await user.click(screen.getByRole('button', { name: '가입' }));

// 기다림 — 임의의 sleep 대신 「조건이 될 때까지」
await screen.findByText('가입 완료');          // 나타날 때까지
await waitForElementToBeRemoved(spinner);      // 사라질 때까지

// 하면 안 되는 것
await new Promise(r => setTimeout(r, 1000));   // 깜빡임의 원인 (6장)

beforeEach(() => {
  localStorage.clear();
  server.resetHandlers();
  vi.setSystemTime(new Date('2026-01-01T00:00:00Z'));   // 시계 고정
});

// 각 테스트가 자기 자료를 만든다 (공유 픽스처 대신)
const user = makeUser({ name: '테스트' + crypto.randomUUID() });

// 순서 의존을 잡아내려면 무작위 순서로 돌려 보라
